class Body {
    constructor(x, y, w, h, type) {
        this.x = x; // center
        this.y = y;
        this.w = w;
        this.h = h;
        this.vx = 0;
        this.vy = 0;
        this.angle = 0;
        this.angularVel = 0;
        this.mass = ... ;
        this.invMass = ...;
        this.inertia = ...;
        this.invInertia = ...;
        this.restitution = 0.2;
        this.friction = 0.5;
        this.type = type; // 'box', 'pig', 'bird'
        this.alive = true;
        this.health = 100;
    }

    getVertices() {
        const c = Math.cos(this.angle);
        const s = Math.sin(this.angle);
        const hw = this.w / 2;
        const hh = this.h / 2;
        return [
            {x: this.x + (-hw*c - -hh*s), y: this.y + (-hw*s + -hh*c)},
            {x: this.x + (hw*c - -hh*s), y: this.y + (hw*s + -hh*c)},
            {x: this.x + (hw*c - hh*s), y: this.y + (hw*s + hh*c)},
            {x: this.x + (-hw*c - hh*s), y: this.y + (-hw*s + hh*c)}
        ];
    }
}
