SAT implementation:
```javascript
function satCollision(bodyA, bodyB) {
    const vertsA = bodyA.getVertices();
    const vertsB = bodyB.getVertices();

    const axesA = getAxes(vertsA);
    const axesB = getAxes(vertsB);
    const axes = [...axesA, ...axesB];

    let minOverlap = Infinity;
    let smallestAxis = null;

    for (const axis of axes) {
        const projA = projectPolygon(vertsA, axis);
        const projB = projectPolygon(vertsB, axis);

        if (projA.max < projB.min || projB.max < projA.min) {
            return null; // separating axis found
        }

        const overlap = Math.min(projA.max, projB.max) - Math.max(projA.min, projB.min);
        if (overlap < minOverlap) {
            minOverlap = overlap;
            smallestAxis = axis;
        }
    }

    // Ensure normal points from A to B
    const dirX = bodyB.x - bodyA.x;
    const dirY = bodyB.y - bodyA.y;
    if (dirX * smallestAxis.x + dirY * smallestAxis.y < 0) {
        smallestAxis = {x: -smallestAxis.x, y: -smallestAxis.y};
    }

    // Find contact point - approximate using deepest vertex
    let contactPoint = findContactPoint(vertsA, vertsB, smallestAxis);

    return {
        normal: smallestAxis,
        depth: minOverlap,
        contact: contactPoint
    };
}
```

Impulse resolution with rotation:
```javascript
function resolveCollision(a, b, manifold) {
    const n = manifold.normal;
    const cp = manifold.contact;

    const rax = cp.x - a.x;
    const ray = cp.y - a.y;
    const rbx = cp.x - b.x;
    const rby = cp.y - b.y;

    // Relative velocity at contact point
    const vax = a.vx - a.angularVel * ray;
    const vay = a.vy + a.angularVel * rax;
    const vbx = b.vx - b.angularVel * rby;
    const vby = b.vy + b.angularVel * rbx;

    const rvx = vbx - vax;
    const rvy = vby - vay;

    const velAlongNormal = rvx * n.x + rvy * n.y;
    if (velAlongNormal > 0) return; // moving apart

    const e = Math.min(a.restitution, b.restitution);

    const raCrossN = rax * n.y - ray * n.x;
    const rbCrossN = rbx * n.y - rby * n.x;

    const invMassSum = a.invMass + b.invMass +
                       raCrossN*raCrossN*a.invInertia +
                       rbCrossN*rbCrossN*b.invInertia;

    const j = -(1+e) * velAlongNormal / invMassSum;

    const impulseX = j * n.x;
    const impulseY = j * n.y;

    a.vx -= impulseX * a.invMass;
    a.vy -= impulseY * a.invMass;
    a.angularVel -= raCrossN * j * a.invInertia;

    b.vx += impulseX * b.invMass;
    b.vy += impulseY * b.invMass;
    b.angularVel += rbCrossN * j * b.invInertia;

    // Friction
    const tangent = {x: -n.y, y: n.x};
    const velAlongTangent = rvx * tangent.x + rvy * tangent.y;
    const jt = -velAlongTangent / invMassSum;

    const mu = Math.sqrt(a.friction * b.friction);
    let frictionJ = jt;
    if (Math.abs(frictionJ) > j * mu) {
        frictionJ = j * mu * Math.sign(jt);
    }

    a.vx -= frictionJ * tangent.x * a.invMass;
    a.vy -= frictionJ * tangent.y * a.invMass;
    a.angularVel -= (rax * tangent.y - ray * tangent.x) * frictionJ * a.invInertia;

    b.vx += frictionJ * tangent.x * b.invMass;
    b.vy += frictionJ * tangent.y * b.invMass;
    b.angularVel += (rbx * tangent.y - rby * tangent.x) * frictionJ * b.invInertia;
}
```

Position correction (to prevent sinking):
```javascript
function positionalCorrection(a, b, manifold) {
    const percent = 0.4;
    const slop = 0.05;
    const correctionMag = Math.max(manifold.depth - slop, 0) / (a.invMass + b.invMass) * percent;
    const cx = manifold.normal.x * correctionMag;
    const cy = manifold.normal.y * correctionMag;
    a.x -= cx * a.invMass;
    a.y -= cy * a.invMass;
    b.x += cx * b.invMass;
    b.y += cy * b.invMass;
}
```

