```js
function update(dt){
    // Cap dt
    dt = Math.min(dt, 1/30);

    // Substep for stability
    const steps = 4;
    const subdt = dt/steps;
    for(let i=0;i<steps;i++){
        physicsStep(subdt);
    }

    // Update particles
    updateParticles(dt);

    // Check win condition
    const pigsLeft = bodies.filter(b=>b.kind==='pig' && b.alive).length;
    if(pigsLeft===0){
        // level complete!
        awardStarsAndAdvance();
    } else if(birdsRemaining<=0 && !activeBird && projectilesResting()){
        // lose
        state='lost';
    }
}

function physicsStep(dt){
    // Integrate
    for(const b of bodies){
        if(!b.alive) continue;
        if(b.static) continue;
        if(b.sleeping) continue;

        b.vy += GRAVITY*dt;
        b.vx *= 0.999; // air resistance tiny
        b.x += b.vx*dt;
        b.y += b.vy*dt;
        b.angle += b.av*dt;
        b.av *= 0.98;
    }

    // Collisions
    // Broad phase: brute force pairwise
    for(let i=0;i<bodies.length;i++){
        for(let j=i+1;j<bodies.length;j++){
            const a=bodies[i], b=bodies[j];
            if(!a.alive||!b.alive) continue;

            // wake if needed
            if((a.sleeping||b.sleeping)){
                // quick check if close enough
                const dx=a.x-b.x, dy=a.y-b.y;
                if(Math.abs(dx)>200||Math.abs(dy)>200) continue;
                a.sleeping=false;b.sleeping=false;
            }

            const result = collide(a,b);
            if(result){
                resolveCollision(a,b,result);
                positionalCorrection(a,b,result);

                // Damage pigs based on impact magnitude
                const relSpeed = Math.hypot(a.vx-b.vx, a.vy-b.vy);
                if(relSpeed>400){
                    spawnImpactParticles(result.contact.x, result.contact.y, relSpeed);
                    if(a.kind==='pig') damagePig(a, relSpeed);
                    if(b.kind==='pig') damagePig(b, relSpeed);
                }
            }
        }
    }

    // Ground collision
    for(const b of bodies){
        if(!b.alive||b.static) continue;
        collideWithGround(b);
    }

    // Sleep management
    for(const b of bodies){
        if(b.static||!b.alive) continue;
        const speedSq = b.vx*b.vx+b.vy*b.vy+b.av*b.av*100;
        if(speedSq<5){
            b.sleepTimer+=dt;
            if(b.sleepTimer>0.5){b.sleeping=true;b.vx=0;b.vy=0;b.av=0;}
        }else{
            b.sleepTimer=0;
            b.sleeping=false;
        }
    }
}
```

Collide function dispatches based on shape:
```js
function collide(a,b){
    if(a.shape==='circle'&&b.shape==='circle') return circleVsCircle(a,b);
    if(a.shape==='circle'&&b.shape==='poly') return circleVsPoly(a,b);
    if(a.shape==='poly'&&b.shape==='circle'){
        const m=circleVsPoly(b,a);
        if(m){m.normal={x:-m.normal.x,y:-m.normal.y};return m;}
    }
    if(a.shape==='poly'&&b.shape==='poly') return polyVsPoly(a,b);
    return null;
}
```

