```js
function circleVsCircle(a,b){
    const dx=b.x-a.x, dy=b.y-a.y;
    const dist=Math.hypot(dx,dy);
    const sumR=a.r+b.r;
    if(dist>=sumR) return null;
    const nx=dist>0?dx/dist:1, ny=dist>0?dy/dist:0;
    return {
        normal:{x:nx,y:ny},
        depth:sumR-dist,
        contact:{x:a.x+nx*a.r, y:a.y+ny*a.r}
    };
}
```

