```js
function circleVsPoly(c, p){
    // transform circle center to p's local coords
    const cos=Math.cos(-p.angle), sin=Math.sin(-p.angle);
    const lx=(c.x-p.x)*cos-(c.y-p.y)*sin;
    const ly=(c.x-p.x)*sin+(c.y-p.y)*cos;

    const hw=p.w/2, hh=p.h/2;
    // closest point on box to circle center
    const qx=Math.max(-hw,Math.min(hw,lx));
    const qy=Math.max(-hh,Math.min(hh,ly));

    const ddx=lx-qx, ddy=ly-qy;
    const distSq=ddx*ddx+ddy*ddy;
    if(distSq>c.r*c.r) return null;

    const dist=Math.sqrt(distSq);
    let nlx,nly;
    if(dist>0.001){
        nlx=ddx/dist;nly=ddy/dist;
    }else{
        // Center inside box - push along minimum penetration axis
        const dxRight=hw-lx, dxLeft=lx+hw;
        const dyTop=hh-ly, dyBot=ly+hh;
        const minPen=Math.min(dxRight,dxLeft,dyTop,dyBot);
        if(minPen===dxRight){nlx=1;nly=0;}
        else if(minPen===dxLeft){nlx=-1;nly=0;}
        else if(minPen===dyTop){nlx=0;nly=1;}
        else{nlx=0;nly=-1;}
    }

    // Rotate normal back to world
    const cosW=Math.cos(p.angle), sinW=Math.sin(p.angle);
    const nx=nlx*cosW-nly*sinW;
    const ny=nlx*sinW+nly*cosW;

    // Contact point on circle surface
    const contact={x:c.x+nx*c.r, y:c.y+ny*c.r};

    // Depth
    const depth = c.r - dist;

    // Make sure normal points from c to p... wait convention?
    // In our resolveCollision, normal points from A to B
    // Here A=c (first arg), B=p (second arg)... so normal should point from c to p
    // Currently nx,ny points from box toward circle (since ddx is from box-closest-point to circle center)
    // We want opposite: from circle to box
    return {
        normal:{x:-nx,y:-ny},
        depth:depth,
        contact:contact
    };
}
```

