Polygon vs Polygon (SAT):
```js
function polyVsPoly(a,b){
    const va=getVerts(a);
    const vb=getVerts(b);

    const axes=[...getEdges(va), ...getEdges(vb)];

    let minOverlap=Infinity;
    let bestAxis=null;

    for(const ax of axes){
        const pa=project(va,ax);
        const pb=project(vb,ax);
        if(pa.max<pb.min||pb.max<pa.min) return null;
        const o=Math.min(pa.max,pb.max)-Math.max(pa.min,pb.min);
        if(o<minOverlap){minOverlap=o;bestAxis=ax;}
    }

    // Orient normal from a to b
    const dx=b.x-a.x, dy=b.y-a.y;
    if(dx*bestAxis.x+dy*bestAxis.y<0){
        bestAxis={x:-bestAxis.x,y:-bestAxis.y};
    }

    // Approximate contact point: average of deepest vertices
    const contact=findContact(va,vb,bestAxis);

    return {normal:bestAxis, depth:minOverlap, contact};
}

function getVerts(b){
    const c=Math.cos(b.angle), s=Math.sin(b.angle);
    const hw=b.w/2, hh=b.h/2;
    const corners=[[-hw,-hh],[hw,-hh],[hw,hh],[-hw,hh]];
    return corners.map(([cx,cy])=>({
        x:b.x+cx*c-cy*s,
        y:b.y+cx*s+cy*c
    }));
}

function getEdges(verts){
    const axes=[];
    for(let i=0;i<verts.length;i++){
        const v1=verts[i],v2=verts[(i+1)%verts.length];
        const ex=v2.x-v1.x, ey=v2.y-v1.y;
        // perpendicular
        const len=Math.hypot(ex,ey)||1;
        axes.push({x:-ey/len, y:ex/len});
    }
    return axes;
}

function project(verts,axis){
    let mn=Infinity,mx=-Infinity;
    for(const v of verts){
        const p=v.x*axis.x+v.y*axis.y;
        if(p<mn)mn=p;if(p>mx)mx=p;
    }
    return {min:mn,max:mx};
}

function findContact(va,vb,axis){
    // Find vertex of va furthest in -axis direction (deepest into b)
    // And vice versa, take midpoint
    let deepA=null,minA=Infinity;
    for(const v of va){
        const p=v.x*(-axis.x)+v.y*(-axis.y);
        if(p<minA){minA=p;deepA=v;}
    }
    let deepB=null,minB=Infinity;
    for(const v of vb){
        const p=v.x*(axis.x)+v.y*(axis.y);
        if(p<minB){minB=p;deepB=v;}
    }
    return {x:(deepA.x+deepB.x)/2, y:(deepA.y+deepB.y)/2};
}
```

Resolve collision with rotation:
```js
function resolveCollision(a,b,m){
    const n=m.normal;
    const cp=m.contact;

    const rax=cp.x-a.x, ray=cp.y-a.y;
    const rbx=cp.x-b.x, rby=cp.y-b.y;

    // Velocities at contact point
    const vax=a.vx-a.av*ray;
    const vay=a.vy+a.av*rax;
    const vbx=b.vx-b.av*rby;
    const vby=b.vy+b.av*rbx;

    const rvx=vbx-vax, rvy=vby-vay;
    const vn=rvx*n.x+rvy*n.y;
    if(vn>0)return; // separating

    const e=Math.min(a.rest||0.2, b.rest||0.2);

    const racn=rax*n.y-ray*n.x;
    const rbcn=rbx*n.y-rby*n.x;

    const imSum=a.im+b.im+racn*racn*a.iI+rbcn*rbcn*b.iI;
    if(imSum===0)return;

    const j=-(1+e)*vn/imSum;

    const ix=j*n.x, iy=j*n.y;
    a.vx-=ix*a.im;a.vy-=iy*a.im;
    a.av-=racn*j*a.iI;
    b.vx+=ix*b.im;b.vy+=iy*b.im;
    b.av+=rbcn*j*b.iI;

    // Friction
    const t={x:-n.y,y:n.x};
    const vt=rvx*t.x+rvy*t.y;
    const jt=-vt/imSum;
    const mu=Math.sqrt((a.fric||0.5)*(b.fric||0.5));
    let fj=jt;
    if(Math.abs(fj)>j*mu)fj=j*mu*Math.sign(jt);

    const fx=fj*t.x, fy=fj*t.y;
    a.vx-=fx*a.im;a.vy-=fy*a.im;
    a.av-=(rax*t.y-ray*t.x)*fj*a.iI;
    b.vx+=fx*b.im;b.vy+=fy*b.im;
    b.av+=(rbx*t.y-rby*t.x)*fj*b.iI;
}
```

