function collideWithGround(b){
    if(b.shape==='circle'){
        const bot=b.y+b.r;
        if(bot>GROUND_Y){
            const depth=bot-GROUND_Y;
            b.y-=depth;
            if(b.vy>0){
                const rest=0.35;
                b.vy=-b.vy*rest;
                if(Math.abs(b.vy)<30)b.vy=0;
                // friction
                b.vx*=0.85;
                b.av*=0.85;
            }
            // Spawn dust
            if(Math.abs(b.vy)>200)spawnDust(b.x,GROUND_Y);
        }
    } else {
        // Poly - check lowest vertex
        const verts=getVerts(b);
        let maxDepth=0, contactVert=null;
        for(const v of verts){
            if(v.y>GROUND_Y&&v.y-GROUND_Y>maxDepth){
                maxDepth=v.y-GROUND_Y;
                contactVert=v;
            }
        }
        if(maxDepth>0){
            // Push up
            b.y-=maxDepth;
            // Resolve like collision with static ground
            // Normal is straight up (from ground to body)
            const fakeManifold={
                normal:{x:0,y:-1}, // from ground(A) to body(B)? hmm
                depth:maxDepth,
                contact:{x:contactVert.x,y:GROUND_Y}
            };
            // Wait, our convention: normal from A to B
            // If A=ground(static below), B=body above, normal points UP from ground to body => {0,-1} in screen coords (y down)
            // Yes correct

            // Create temporary static body for ground
            const ground={x:0,y:GROUND_Y,vx:0,vy:0,av:0,im:0,iI:0,rest:0.3,fric:0.7};
            // Adjust: pass body as second arg (B), ground as first (A)
            resolveCollision(ground,b,fakeManifold);
            positionalCorrection(ground,b,fakeManifold);

            if(Math.abs(b.vy)>250)spawnDust(contactVert.x,GROUND_Y);
        }
    }
}
