While dragging, compute predicted path under gravity ignoring collisions:
```js
function predictTrajectory(startX,startY,vx,vy){
    const pts=[];
    let x=startX,y=startY,vx2=vx,vy2=vy;
    const dt=0.04;
    for(let i=0;i<60;i++){
        vy2+=GRAVITY*dt;
        x+=vx2*dt;y+=vy2*dt;
        pts.push({x,y});
        if(y>GROUND_Y)break;
        if(x>W||x<0)break;
    }
    return pts;
}
