```js
function startLevel(idx){
    currentLevel=idx;
    bodies=[];particles=[];
    const lvl=LEVELS[idx];
    birdsRemaining=lvl.birds||3;
    birdsUsed=0;
    for(const item of lvl.setup){
        if(item.type==='box'){
            bodies.push(makeBox(item.x,item.y,item.w,item.h));
        }else if(item.type==='pig'){
            bodies.push(makePig(item.x,item.y,item.r||22));
        }
    }
    loadBirdOnSling();
    state='playing';
}

function loadBirdOnSling(){
    if(birdsRemaining<=0){activeBird=null;return;}
    activeBird={
        kind:'bird',shape:'circle',
        x:SLING.x,y:SLING.y,
        vx:0,vy:0,angle:0,av:0,
        r:18,mass:5,im:1/5,inertia:0.5*5*18*18,iI:1/(0.5*5*18*18),
        rest:0.3,fric:0.5,
        alive:true,onSling:true,sleeping:false,sleepTimer:0,
        launched:false
    };
}

function launchBird(){
    if(!activeBird||!dragging)return;
    const dx=SLING.x-dragPos.x, dy=SLING.y-dragPos.y;
    const mag=Math.hypot(dx,dy);
    if(mag<10){dragging=false;return;} // ignore tiny pulls
    const clamped=Math.min(mag,MAX_DRAG);
    const ux=dx/mag, uy=dy/mag;
    const speed=clamped*LAUNCH_SCALE;
    activeBird.vx=ux*speed;
    activeBird.vy=uy*speed;
    activeBird.onSling=false;
    activeBird.launched=true;
    activeBird.x=dragPos.x;
    activeBird.y=dragPos.y;
    bodies.push(activeBird);
    birdsRemaining--;
    birdsUsed++;
    dragging=false;
    // Schedule reload after delay or when settled
    setTimeout(()=>{},0); // placeholder
}
