    if(!activeBird)return;
    if(activeBird.onSling)return;
    // Conditions to retire current bird:
    const offscreen = activeBird.x<-50||activeBird.x>W+50||activeBird.y>H+50;
    const slowEnough = Math.hypot(activeBird.vx,activeBird.vy)<30 && activeBird.sleeping;
