// Fix any negative y values quickly
LEVELS.forEach(lv=>lv.setup.forEach(it=>{if(it.y<it.r||it.y<it.h/2)console.warn("bad");}));

// ---------- Factory ----------
let _idCounter=0;
function makeBox(x,y,w,h){
  const mass=w*h*0.0025;
  return {
    id:_idCounter++,
    kind:"box",shape:"poly",
    x,y,w,h,
    vx:0,vy:0,angle:0,av:0,
