    inertia:mass*(w*w+h*h)/12,iI:12/(mass*(w*w+h*h)),
    rest:0.15,fric:0.7,
    alive:true,sleeping:false,sleepTimer:0,
    damage:0,maxDamage:100,
    crackPattern:genCrackPattern(),
  };
}
function makePig(x,y,r){
  const mass=r*r*0.01;
  return {
    id:_idCounter++,
    kind:"pig",shape:"circle",
    x,y,r,
    vx:0,vy:0,angle:0,av:0,
    mass,im:1/mass,
    inertia:0.5*mass*r*r,iI:1/(0.5*mass*r*r),
    rest:0.25,fric:0.6,
    alive:true,sleeping:false,sleepTimer:0,
    health:100,maxHealth:100,
    crackSeed:Math.random()*Math.PI*2,
  };
}
function genCrackPattern(){
  const arr=[];
  for(let i=0;i<6;i++)arr.push({a:Math.random()*Math.PI*2,len:0.3+Math.random()*0.5,jitter:(Math.random()-0.5)*0.4});
  return arr;
}

// ---------- Geometry helpers ----------
function getVerts(b){
  const c=Math.cos(b.angle),s=Math.sin(b.angle);
  const hw=b.w/2,hh=b.h/2;
  return [
    {x:b.x+(-hw)*c-(-hh)*s, y:b.y+(-hw)*s+(-hh)*c},
    {x:b.x+( hw)*c-(-hh)*s, y:b.y+( hw)*s+(-hh)*c},
    {x:b.x+( hw)*c-( hh)*s, y:b.y+( hw)*s+( hh)*c},
    {x:b.x+(-hw)*c-( hh)*s, y:b.y+(-hw)*s+( hh)*c},
  ];
}

// ---------- Collision detection ----------
function collide(a,b){
  if(a.shape==="circle"&&b.shape==="circle")return circCirc(a,b);
  if(a.shape==="circle"&&b.shape==="poly"){
    const m=circPoly(a,b);
    return m;
  }
  if(a.shape==="poly"&&b.shape==="circle"){
    const m=circPoly(b,a);
    if(m)m.normal={x:-m.normal.x,y:-m.normal.y};
    return m;
  }
  if(a.shape==="poly"&&b.shape==="poly")return polyPoly(a,b);
  return null;
}

function circCirc(a,b){
  const dx=b.x-a.x,dy=b.y-a.y;
  const d=Math.hypot(dx,dy);
  const sr=a.r+b.r;
  if(d>=sr)return null;
  const nx=d>0?dx/d:1, ny=d>0?dy/d:0;
  return {normal:{x:nx,y:ny},depth:sr-d,contact:{x:a.x+nx*a.r,y:a.y+ny*a.r}};
}

function circPoly(c,p){
  const cs=Math.cos(-p.angle),sn=Math.sin(-p.angle);
  const lx=(c.x-p.x)*cs-(c.y-p.y)*sn;
  const ly=(c.x-p.x)*sn+(c.y-p.y)*cs;
  const hw=p.w/2,hh=p.h/2;
  const qx=Math.max(-hw,Math.min(hw,lx));
  const qy=Math.max(-hh,Math.min(hh,ly));
  const dx=lx-qx,dy=ly-qy;
  const dsq=dx*dx+dy*dy;
  if(dsq>c.r*c.r)return null;
  const d=Math.sqrt(dsq);
  let nlx,nly;
  if(d>0.001){nlx=dx/d;nly=dy/d;}
  else{
    const penR=hw-lx,penL=lx+hw,penT=hh-ly,penB=ly+hh;
    const mp=Math.min(penR,penL,penT,penB);
    if(mp===penR){nlx=1;nly=0;}
    else if(mp===penL){nlx=-1;nly=0;}
    else if(mp===penT){nlx=0;nly=1;}
    else{nlx=0;nly=-1;}
  }
  const cw=Math.cos(p.angle),sw=Math.sin(p.angle);
  const wx=nlx*cw-nly*sw, wy=nlx*sw+nly*cw;
  // wx,wy points from box surface outward toward circle
  // Convention: normal from A(circle) to B(poly) → reverse
  return {
    normal:{x:-wx,y:-wy},
    depth:d>0.001?c.r-d:c.r,
    contact:{x:c.x-wx*c.r,y:c.y-wy*c.r},
  };
}

function polyPoly(a,b){
  const va=getVerts(a),vb=getVerts(b);
  const axes=[...edgeNormals(va),...edgeNormals(vb)];
  let minO=Infinity,best=null;
  for(const ax of axes){
    const pa=proj(va,ax),pb=proj(vb,ax);
    if(pa.max<pb.min||pb.max<pa.min)return null;
    const o=Math.min(pa.max,pb.max)-Math.max(pa.min,pb.min);
    if(o<minO){minO=o;best=ax;}
  }
  const dx=b.x-a.x,dy=b.y-a.y;
  if(dx*best.x+dy*best.y<0)best={x:-best.x,y:-best.y};
  const ct=approxContact(va,vb,best);
  return {normal:best,depth:minO,contact:ct};
}
function edgeNormals(vs){
  const out=[];
  for(let i=0;i<vs.length;i++){
    const v1=vs[i],v2=vs[(i+1)%vs.length];
    const ex=v2.x-v1.x,ey=v2.y-v1.y;
    const l=Math.hypot(ex,ey)||1;
    out.push({x:-ey/l,y:ex/l});
  }
  return out;
}
function proj(vs,axis){
  let mn=Infinity,mx=-Infinity;
  for(const v of vs){
    const p=v.x*axis.x+v.y*axis.y;
    if(p<mn)mn=p;if(p>mx)mx=p;
  }
  return {min:mn,max:mx};
}
function approxContact(va,vb,axis){
  // Deepest vertex of va in -axis dir, deepest of vb in +axis dir
  let da=null,daMin=Infinity;
  for(const v of va){
    const p=-v.x*axis.x-v.y*axis.y;
    if(p<daMin){daMin=p;da=v;}
  }
  let db=null,dbMin=Infinity;
  for(const v of vb){
    const p=v.x*axis.x+v.y*axis.y;
    if(p<dbMin){dbMin=p;db=v;}
  }
  return {x:(da.x+db.x)/2,y:(da.y+db.y)/2};
}

// ---------- Resolution ----------
function resolve(a,b,m){
  const n=m.normal,cp=m.contact;
  const rax=cp.x-a.x,ray=cp.y-a.y;
  const rbx=cp.x-b.x,rby=cp.y-b.y;
  const vax=a.vx-a.av*ray;
  const vay=a.vy+a.av*rax;
  const vbx=b.vx-b.av*rby;
  const vby=b.vy+b.av*rbx;
  const rvx=vbx-vax,rvy=vby-vay;
  const vn=rvx*n.x+rvy*n.y;
  if(vn>0)return 0;
  const e=Math.min(a.rest,b.rest);
  const racn=rax*n.y-ray*n.x;
  const rbcn=rbx*n.y-rby*n.x;
  const ims=a.im+b.im+racn*racn*a.iI+rbcn*rbcn*b.iI;
  if(ims===0)return 0;
  const j=-(1+e)*vn/ims;
  const ix=j*n.x,iy=j*n.y;
  a.vx-=ix*a.im;a.vy-=iy*a.im;a.av-=racn*j*a.iI;
  b.vx+=ix*b.im;b.vy+=iy*b.im;b.av+=rbcn*j*b.iI;
  // Friction
  const tx=-n.y,ty=n.x;
  const vt=rvx*tx+rvy*ty;
  let jt=-vt/ims;
  const mu=Math.sqrt(a.fric*b.fric);
  if(Math.abs(jt)>Math.abs(j)*mu)jt=Math.abs(j)*mu*Math.sign(jt);
  a.vx-=tx*jt*a.im;a.vy-=ty*jt*a.im;
  a.av-=(rax*ty-ray*tx)*jt*a.iI;
  b.vx+=tx*jt*b.im;b.vy+=ty*jt*b.im;
  b.av+=(rbx*ty-rby*tx)*jt*b.iI;
  return Math.abs(vn);
}

function positionalCorrect(a,b,m){
  const pct=0.6,slop=0.05;
  const ims=a.im+b.im;
  if(ims===0)return;
  const corr=Math.max(m.depth-slop,0)/ims*pct;
  a.x-=corr*m.normal.x*a.im;
  a.y-=corr*m.normal.y*a.im;
  b.x+=corr*m.normal.x*b.im;
  b.y+=corr*m.normal.y*b.im;
}

function collideGround(b){
  if(b.shape==="circle"){
    const bot=b.y+b.r;
    if(bot>GROUND_Y){
      const depth=bot-GROUND_Y;
      b.y-=depth;
      const ground={x:0,y:GROUND_Y,vx:0,vy:0,av:0,im:0,iI:0,rest:0.3,fric:0.9};
      const m={normal:{x:0,y:-1},depth,contact:{x:b.x,y:GROUND_Y}};
      const imp=resolve(ground,b,m);
      if(imp>200){addShake(imp*0.02);spawnDust(b.x,GROUND_Y,6);}
    }
  }else{
    const vs=getVerts(b);
    let md=0,cv=null;
    for(const v of vs){
      if(v.y>GROUND_Y&&v.y-GROUND_Y>md){md=v.y-GROUND_Y;cv=v;}
    }
    if(md>0){
      b.y-=md;
      const ground={x:0,y:GROUND_Y,vx:0,vy:0,av:0,im:0,iI:0,rest:0.3,fric:0.9};
      const m={normal:{x:0,y:-1},depth:md,contact:{x:cv?cv.x:b.x,y:GROUND_Y}};
      const imp=resolve(ground,b,m);
      if(imp>250){addShake(imp*0.015);spawnDust(cv?cv.x:b.x,GROUND_Y,8);}
    }
  }
}

// ---------- Physics step ----------
function physicsStep(dt){
  // Integrate
  for(const b of bodies){
    if(!b.alive||b.sleeping)continue;
    b.vy+=GRAVITY*dt;
    b.vx*=0.998;
    b.vy*=0.998;
    b.av*=0.985;
    // Clamp extreme velocities
    const vm=Math.hypot(b.vx,b.vy);
    if(vm>2200){b.vx*=2200/vm;b.vy*=2200/vm;}
    if(Math.abs(b.av)>30)b.av=30*Math.sign(b.av);
    b.x+=b.vx*dt;
    b.y+=b.vy*dt;
    b.angle+=b.av*dt;
  }

  // Pairwise collisions
  for(let i=0;i<bodies.length;i++){
    const a=bodies[i];if(!a.alive)continue;
    for(let j=i+1;j<bodies.length;j++){
      const b=bodies[j];if(!b.alive)continue;
      if(a.sleeping&&b.sleeping)continue;
      // Quick reject
      const radA=a.shape==="circle"?a.r:Math.hypot(a.w,a.h)/2;
      const radB=b.shape==="circle"?b.r:Math.hypot(b.w,b.h)/2;
      const dd=Math.hypot(a.x-b.x,a.y-b.y);
      if(dd>radA+radB+5)continue;

      const m=collide(a,b);
      if(m){
        // Wake
        a.sleeping=false;b.sleeping=false;a.sleepTimer=0;b.sleepTimer=0;
        const imp=resolve(a,b,m);
        positionalCorrect(a,b,m);

        if(imp>180){
          spawnDust(m.contact.x,m.contact.y,Math.min(10,imp*0.03));
          if(a.kind==="pig")damagePig(a,imp);
          if(b.kind==="pig")damagePig(b,imp);
          if(a.kind==="box")damageBox(a,imp);
          if(b.kind==="box")damageBox(b,imp);
          if(a.kind==="bird"){damageNearbyPigsFromBird(a,imp);}
          if(b.kind==="bird"){damageNearbyPigsFromBird(b,imp);}
        }
      }
    }
  }

  // Ground
  for(const b of bodies){
    if(!b.alive)continue;
    collideGround(b);
  }

  // Walls (off-screen cleanup happens later)
  for(const b of bodies){
    if(!b.alive)continue;
    if(b.x<-100||b.x>W+100||b.y>H+100){
      b.alive=false;
      if(b.kind==="bird"&&b===activeBird){}
    }
  }

  // Sleep mgmt
  for(const b of bodies){
    if(!b.alive||b.kind==="bird")continue;
    const sq=b.vx*b.vx+b.vy*b.vy+b.av*b.av*40;
    if(sq<8){
      b.sleepTimer+=dt;
      if(b.sleepTimer>0.6){b.sleeping=true;b.vx=0;b.vy=0;b.av=0;}
    }else{
      b.sleepTimer=0;b.sleeping=false;
    }
  }
}

// ---------- Damage ----------
function damagePig(p,imp){
  if(!p.alive)return;
  const dmg=Math.max(0,imp-150)*0.25;
  p.health-=dmg;
  if(p.health<=0){
    p.alive=false;
    spawnPop(p.x,p.y);
    addShake(6);
    score+=5000;
  }
}
function damageBox(b,imp){
  if(!b.alive)return;
  b.damage+=Math.max(0,imp-280)*0.18;
  if(b.damage>b.maxDamage){
    b.alive=false;
    spawnDebris(b);
    score+=500;
  }
}
function damageNearbyPigsFromBird(bird,imp){
  // Already handled by pair collision damage; nothing extra needed.
}

// ---------- Particles ----------
function spawnDust(x,y,n=6){
  for(let i=0;i<n;i++){
    particles.push({
      x:x+(Math.random()-0.5)*8,y:y+(Math.random()-0.5)*4,
      vx:(Math.random()-0.5)*180,vy:-Math.random()*120-30,
      life:0.5+Math.random()*0.4,age:0,
      r:2+Math.random()*3,
      color:["#d9c79b","#cdb483","#b89e6a"][Math.floor(Math.random()*3)],
      grav:300,
    });
  }
}
function spawnPop(x,y){
  for(let i=0;i<22;i++){
    const a=Math.random()*Math.PI*2;
    const sp=120+Math.random()*220;
    particles.push({
      x,y,vx:Math.cos(a)*sp,vy:Math.sin(a)*sp,
      life:0.7+Math.random()*0.3,age:0,
      r:3+Math.random()*4,
      color:["#7ec850","#5fa83a","#a3df74"][Math.floor(Math.random()*3)],
      grav:600,
    });
  }
}
function spawnDebris(box){
  for(let i=0;i<14;i++){
    const a=Math.random()*Math.PI*2;
    const sp=80+Math.random()*180;
    particles.push({
      x:box.x+(Math.random()-0.5)*box.w,
      y:box.y+(Math.random()-0.5)*box.h,
      vx:Math.cos(a)*sp,vy:Math.sin(a)*sp-Math.random()*100,
      life:0.8+Math.random()*0.4,age:0,
      r:2+Math.random()*3,
      color:["#b5793f","#7a4a1a","#a0682f"][Math.floor(Math.random()*3)],
      grav:900,
    });
  }
}
function updateParticles(dt){
  for(let i=particles.length-1;i>=0;i--){
    const p=particles[i];
    p.age+=dt;
    if(p.age>=p.life){particles.splice(i,1);continue;}
    p.vy+=p.grav*dt;
    p.x+=p.vx*dt;p.y+=p.vy*dt;
    p.vx*=0.97;
  }
}

// ---------- Camera shake ----------
function addShake(n){shake=Math.min(shake+n,18);}

// ---------- Game flow ----------
function startLevel(idx){
  currentLevel=idx;
  bodies=[];particles=[];
  const lv=LEVELS[idx];
  birdsRemaining=lv.birds||3;
  birdsUsed=0;
  for(const it of lv.setup){
    if(it.kind==="box")bodies.push(makeBox(it.x,it.y,it.w,it.h));
    else if(it.kind==="pig")bodies.push(makePig(it.x,it.y,it.r));
  }
  activeBird=null;
  loadBirdOnSling();
  state="playing";
  levelEndTimer=0;
  shake=0;
}

function loadBirdOnSling(){
  if(birdsRemaining<=0){activeBird=null;return;}
  activeBird={
    id:_idCounter++,
    kind:"bird",shape:"circle",
    x:SLING.x,y:SLING.y,
    vx:0,vy:0,angle:0,av:0,
    r:18,
    mass:6,im:1/6,
    inertia:0.5*6*18*18,iI:1/(0.5*6*18*18),
    rest:0.25,fric:0.5,
    alive:true,sleeping:false,sleepTimer:0,
    onSling:true,launched:false,timeAlive:0,settleTimer:0,
  };
  dragPos={x:SLING.x,y:SLING.y};
}

function launchBird(){
  if(!activeBird||!activeBird.onSling)return;
  const dx=SLING.x-dragPos.x,dy=SLING.y-dragPos.y;
  const mag=Math.hypot(dx,dy);
  if(mag<12){dragging=false;return;}
  const clamped=Math.min(mag,MAX_DRAG);
  const ux=dx/mag,uy=dy/mag;
  const speed=clamped*LAUNCH_SCALE;
  activeBird.vx=ux*speed;
  activeBird.vy=uy*speed;
  activeBird.x=dragPos.x;
  activeBird.y=dragPos.y;
  activeBird.onSling=false;
  activeBird.launched=true;
  bodies.push(activeBird);
  birdsRemaining--;
  birdsUsed++;
  dragging=false;
  addShake(3);
}

function retireActiveBird(){
  if(!activeBird)return;
  activeBird.alive=false;
  activeBird=null;
  if(birdsRemaining>0){
    setTimeout(loadBirdOnSling,400);
  }
}

function checkProgress(){
  if(state!=="playing")return;
  const pigs=bodies.filter(b=>b.kind==="pig"&&b.alive);
  if(pigs.length===0){
    finishLevel(true);
    return;
  }
  if(birdsRemaining<=0&&!activeBird){
    finishLevel(false);
  }
}

function finishLevel(won){
  if(won){
    const stars=birdsUsed===1?3:birdsUsed===2?2:1;
    lastStars=stars;
    totalStars+=stars;
    const bonus=birdsRemaining*10000;
    score+=bonus;
    if(currentLevel<LEVELS.length-1){
      state="levelComplete";
    }else{
      state="allWon";
    }
  }else{
    state="lost";
  }
}

// ---------- Update ----------
function update(dt){
  if(state!=="playing")return;
  const sd=dt/SUBSTEPS;
  for(let i=0;i<SUBSTEPS;i++)physicsStep(sd);
  updateParticles(dt);

  // Manage active bird retirement
  if(activeBird&&activeBird.launched){
    activeBird.timeAlive+=dt;
    const speed=Math.hypot(activeBird.vx,activeBird.vy);
    if(speed<25&&activeBird.sleeping){
      activeBird.settleTimer+=dt;
      if(activeBird.settleTimer>1.0)retireActiveBird();
    }else{
      activeBird.settleTimer=0;
    }
    if(activeBird&&(activeBird.x<-50||activeBird.x>W+50||activeBird.y>H+50))retireActiveBird();
    if(activeBird&&activeBird.timeAlive>10)retireActiveBird();
  }

  // Clean dead bodies occasionally
  if(bodies.length>0&&Math.random()<0.05){
    bodies=bodies.filter(b=>b.alive);
  }

  checkProgress();
  shake*=0.86;
}

// ---------- Rendering ----------
function render(){
  ctx.clearRect(0,0,W,H);
  drawBackground();

  ctx.save();
  if(shake>0.1)ctx.translate((Math.random()-0.5)*shake,(Math.random()-0.5)*shake);

  drawGround();
  drawSlingBack();
  drawBodies();
  if(activeBird&&activeBird.onSling)drawBirdOnSling();
  drawSlingFront();
  if(dragging&&activeBird&&activeBird.onSling)drawTrajectoryPreview();
  drawParticles();

  ctx.restore();

  drawHUD();
  drawOverlay();
}

function drawBackground(){
  const g=ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,"#5fb4ea");
  g.addColorStop(0.55,"#a8ddf0");
  g.addColorStop(0.85,"#ffe9bf");
  g.addColorStop(1,"#ffd09a");
  ctx.fillStyle=g;
  ctx.fillRect(0,0,W,H);

  // sun
  ctx.save();
  ctx.globalAlpha=0.85;
  const sg=ctx.createRadialGradient(W-160,90,5,W-160,90,80);
  sg.addColorStop(0,"#fff7d0");
  sg.addColorStop(1,"rgba(255,225,150,0)");
  ctx.fillStyle=sg;
  ctx.beginPath();ctx.arc(W-160,90,80,0,Math.PI*2);ctx.fill();
  ctx.restore();

  // distant hills
  ctx.fillStyle="#9fd17a";
  ctx.beginPath();
  ctx.moveTo(0,GROUND_Y);
  ctx.bezierCurveTo(W*0.2,GROUND_Y-70,W*0.4,GROUND_Y-30,W*0.55,GROUND_Y-50);
  ctx.bezierCurveTo(W*0.7,GROUND_Y-80,W*0.85,GROUND_Y-20,W,GROUND_Y-40);
  ctx.lineTo(W,GROUND_Y);ctx.closePath();ctx.fill();

  ctx.fillStyle="#84bd63";
  ctx.beginPath();
  ctx.moveTo(0,GROUND_Y);
  ctx.bezierCurveTo(W*0.15,GROUND_Y-30,W*0.35,GROUND_Y-10,W*0.5,GROUND_Y-25);
  ctx.bezierCurveTo(W*0.7,GROUND_Y-40,W*0.9,GROUND_Y-5,W,GROUND_Y-15);
  ctx.lineTo(W,GROUND_Y);ctx.closePath();ctx.fill();

  // clouds
  for(const c of bgClouds){
    c.x+=c.speed*0.016;
    if(c.x>W+80)c.x=-80;
    drawCloud(c.x,c.y,c.s);
  }
}
function drawCloud(x,y,s){
  ctx.fillStyle="rgba(255,255,255,0.85)";
  ctx.beginPath();
  ctx.arc(x,y,18*s,0,Math.PI*2);
  ctx.arc(x+22*s,y-6*s,22*s,0,Math.PI*2);
  ctx.arc(x+44*s,y,18*s,0,Math.PI*2);
  ctx.arc(x+22*s,y+8*s,16*s,0,Math.PI*2);
  ctx.fill();
}

function drawGround(){
  // dirt
  const gg=ctx.createLinearGradient(0,GROUND_Y,0,H);
  gg.addColorStop(0,"#7a4a23");
  gg.addColorStop(1,"#5a3717");
  ctx.fillStyle=gg;
  ctx.fillRect(0,GROUND_Y,W,H-GROUND_Y);
  // grass top
  ctx.fillStyle="#69b53c";
  ctx.fillRect(0,GROUND_Y-4,W,8);
  ctx.fillStyle="#4d9028";
  for(let x=0;x<W;x+=14){
    ctx.fillRect(x,GROUND_Y-4,3,4);
  }
}

function drawSlingBack(){
  // back fork (behind bird)
  ctx.fillStyle="#5a3018";
  ctx.beginPath();
  ctx.moveTo(SLING.x-12,SLING.y+50);
  ctx.lineTo(SLING.x-12,SLING.y-40);
  ctx.lineTo(SLING.x-2,SLING.y-50);
  ctx.lineTo(SLING.x-2,SLING.y+50);
  ctx.closePath();ctx.fill();
}
function drawSlingFront(){
  // front fork
  ctx.fillStyle="#3d2010";
  ctx.beginPath();
  ctx.moveTo(SLING.x+2,SLING.y+50);
  ctx.lineTo(SLING.x+2,SLING.y-50);
  ctx.lineTo(SLING.x+12,SLING.y-40);
  ctx.lineTo(SLING.x+12,SLING.y+50);
  ctx.closePath();ctx.fill();
  // base
  ctx.fillStyle="#2a1608";
  ctx.fillRect(SLING.x-18,SLING.y+45,36,18);

  // bands
  if(activeBird&&activeBird.onSling){
    ctx.strokeStyle="#3a1810";
    ctx.lineCap="round";
    ctx.lineWidth=5;
    ctx.beginPath();
    ctx.moveTo(SLING.x-7,SLING.y-45);
    ctx.lineTo(activeBird.x,activeBird.y);
    ctx.stroke();
    ctx.lineWidth=4;
    ctx.beginPath();
    ctx.moveTo(SLING.x+7,SLING.y-45);
    ctx.lineTo(activeBird.x,activeBird.y);
    ctx.stroke();
  }
}

function drawBodies(){
  for(const b of bodies){
    if(!b.alive)continue;
    if(b.kind==="box")drawBox(b);
    else if(b.kind==="pig")drawPig(b);
    else if(b.kind==="bird")drawFlyingBird(b);
  }
}

function drawBox(b){
  ctx.save();
  ctx.translate(b.x,b.y);
  ctx.rotate(b.angle);
  const hw=b.w/2,hh=b.h/2;
  // outer dark
  ctx.fillStyle="#6b3f17";
  ctx.fillRect(-hw,-hh,b.w,b.h);
  // inner light
  const lg=ctx.createLinearGradient(0,-hh,0,hh);
  lg.addColorStop(0,"#c08247");
  lg.addColorStop(1,"#9a6837");
  ctx.fillStyle=lg;
  ctx.fillRect(-hw+2,-hh+2,b.w-4,b.h-4);
  // plank seam
  ctx.strokeStyle="#6b3f17";
  ctx.lineWidth=2;
  ctx.beginPath();
  ctx.moveTo(-hw+2,0);ctx.lineTo(hw-2,0);
  ctx.stroke();
  // diagonals
  ctx.lineWidth=1.5;
  ctx.beginPath();
  ctx.moveTo(-hw+4,-hh+4);ctx.lineTo(hw-4,hh-4);
  ctx.moveTo(hw-4,-hh+4);ctx.lineTo(-hw+4,hh-4);
  ctx.stroke();
  // bolts
  ctx.fillStyle="#4a2a10";
  [[-hw+6,-hh+6],[hw-6,-hh+6],[-hw+6,hh-6],[hw-6,hh-6]].forEach(p=>{
    ctx.beginPath();ctx.arc(p[0],p[1],2.2,0,Math.PI*2);ctx.fill();
  });
  // cracks
  if(b.damage>0){
    const ratio=Math.min(b.damage/b.maxDamage,1);
    ctx.strokeStyle=`rgba(40,20,10,${0.4+ratio*0.4})`;
    ctx.lineWidth=1.4;
    const n=Math.floor(ratio*5)+1;
    for(let i=0;i<n;i++){
      const seed=b.id*73+i;
      const sa=(seed%360)/180*Math.PI;
      const len=b.w*0.4*((seed%7)/7+0.3);
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.lineTo(Math.cos(sa)*len,Math.sin(sa)*len*0.7);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function drawPig(p){
  ctx.save();
  ctx.translate(p.x,p.y);
  ctx.rotate(p.angle);
  // body
  const rg=ctx.createRadialGradient(-p.r*0.3,-p.r*0.3,2,0,0,p.r);
  rg.addColorStop(0,"#a3df74");
  rg.addColorStop(1,"#5fa83a");
  ctx.fillStyle=rg;
  ctx.beginPath();ctx.arc(0,0,p.r,0,Math.PI*2);ctx.fill();
  // ears
  ctx.fillStyle="#5fa83a";
  ctx.beginPath();ctx.arc(-p.r*0.55,-p.r*0.7,p.r*0.22,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(p.r*0.55,-p.r*0.7,p.r*0.22,0,Math.PI*2);ctx.fill();
  // inner ear
  ctx.fillStyle="#82c557";
  ctx.beginPath();ctx.arc(-p.r*0.55,-p.r*0.7,p.r*0.11,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(p.r*0.55,-p.r*0.7,p.r*0.11,0,Math.PI*2);ctx.fill();
  // snout
  ctx.fillStyle="#5fa83a";
  ctx.beginPath();ctx.ellipse(0,p.r*0.18,p.r*0.42,p.r*0.32,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle="#3d7028";
  ctx.beginPath();ctx.arc(-p.r*0.14,p.r*0.18,p.r*0.07,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(p.r*0.14,p.r*0.18,p.r*0.07,0,Math.PI*2);ctx.fill();
  // eyes
  ctx.fillStyle="white";
  ctx.beginPath();ctx.arc(-p.r*0.32,-p.r*0.18,p.r*0.18,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(p.r*0.32,-p.r*0.18,p.r*0.18,0,Math.PI*2);ctx.fill();
  ctx.fillStyle="#111";
  ctx.beginPath();ctx.arc(-p.r*0.28,-p.r*0.16,p.r*0.08,0,Math.PI*2);ctx.fill();
  ctx.beginPath();ctx.arc(p.r*0.36,-p.r*0.16,p.r*0.08,0,Math.PI*2);ctx.fill();
  // smile
  ctx.strokeStyle="#3d7028";
  ctx.lineWidth=1.5;
  ctx.beginPath();
  ctx.arc(0,p.r*0.05,p.r*0.18,0.2*Math.PI,0.8*Math.PI);
  ctx.stroke();
  // damage cracks
  if(p.health<p.maxHealth){
    const ratio=1-p.health/p.maxHealth;
    ctx.strokeStyle=`rgba(40,80,20,${0.5+ratio*0.3})`;
    ctx.lineWidth=1.5;
    const n=Math.floor(ratio*5)+1;
    for(let i=0;i<n;i++){
      const sa=p.crackSeed+i*Math.PI*2/n;
      ctx.beginPath();
      ctx.moveTo(0,0);
      ctx.lineTo(Math.cos(sa)*p.r*0.7,Math.sin(sa)*p.r*0.7);
      ctx.stroke();
    }
  }
  ctx.restore();

  // health bar (untransformed)
  if(p.health<p.maxHealth&&p.alive){
    const bw=p.r*1.6,bh=5;
    ctx.fillStyle="rgba(0,0,0,0.5)";
    ctx.fillRect(p.x-bw/2,p.y-p.r-12,bw,bh);
    const hr=p.health/p.maxHealth;
    ctx.fillStyle=hr>0.5?"#7ed957":hr>0.25?"#ffd34d":"#ff4444";
    ctx.fillRect(p.x-bw/2,p.y-p.r-12,bw*hr,bh);
  }
}

function drawFlyingBird(b){
  ctx.save();
  ctx.translate(b.x,b.y);
  ctx.rotate(b.angle);
  drawBirdShape(ctx,b.r);
  ctx.restore();
}
function drawBirdOnSling(){
  ctx.save();
  ctx.translate(activeBird.x,activeBird.y);
  // tilt slightly based on drag
  const dx=SLING.x-activeBird.x,dy=SLING.y-activeBird.y;
  const ang=Math.atan2(dy,dx);
  ctx.rotate(ang-Math.PI/2);
  drawBirdShape(ctx,activeBird.r);
  ctx.restore();
}
function drawBirdShape(g,r){
  // body
  const rg=g.createRadialGradient(-r*0.3,-r*0.3,2,0,0,r);
  rg.addColorStop(0,"#ff5a5a");
  rg.addColorStop(1,"#c41e1e");
  g.fillStyle=rg;
  g.beginPath();g.arc(0,0,r,0,Math.PI*2);g.fill();
  // belly
  g.fillStyle="#ffb3b3";
  g.beginPath();g.ellipse(0,r*0.35,r*0.55,r*0.4,0,0,Math.PI*2);g.fill();
  // tail feathers
  g.fillStyle="#a01818";
  g.beginPath();
  g.moveTo(-r*0.9,-r*0.2);
  g.lineTo(-r*1.2,0);
  g.lineTo(-r*0.9,r*0.2);
  g.closePath();g.fill();
  // eyes white
  g.fillStyle="white";
  g.beginPath();g.arc(r*0.25,-r*0.25,r*0.22,0,Math.PI*2);g.fill();
  g.beginPath();g.arc(r*0.6,-r*0.22,r*0.2,0,Math.PI*2);g.fill();
  // pupils
  g.fillStyle="#111";
  g.beginPath();g.arc(r*0.31,-r*0.22,r*0.1,0,Math.PI*2);g.fill();
  g.beginPath();g.arc(r*0.64,-r*0.21,r*0.09,0,Math.PI*2);g.fill();
  // eyebrow angry
  g.strokeStyle="#333";
  g.lineWidth=2.5;
  g.beginPath();
  g.moveTo(r*0.1,-r*0.5);
  g.lineTo(r*0.7,-r*0.32);
  g.stroke();
  // beak
  g.fillStyle="#f5a623";
  g.beginPath();
  g.moveTo(r*0.7,-r*0.05);
  g.lineTo(r*1.15,r*0.05);
  g.lineTo(r*0.7,r*0.18);
  g.closePath();g.fill();
  g.fillStyle="#d18820";
  g.beginPath();
  g.moveTo(r*0.7,r*0.18);
  g.lineTo(r*1.0,r*0.12);
  g.lineTo(r*0.7,r*0.05);
  g.closePath();g.fill();
}

function drawTrajectoryPreview(){
  const dx=SLING.x-dragPos.x,dy=SLING.y-dragPos.y;
  const mag=Math.hypot(dx,dy);
  if(mag<12)return;
  const clamped=Math.min(mag,MAX_DRAG);
  const ux=dx/mag,uy=dy/mag;
  const speed=clamped*LAUNCH_SCALE;
  let x=dragPos.x,y=dragPos.y,vx=ux*speed,vy=uy*speed;
  const dt=0.04;
  ctx.fillStyle="rgba(255,255,255,0.85)";
  for(let i=0;i<40;i++){
    vy+=GRAVITY*dt;
    x+=vx*dt;y+=vy*dt;
    if(y>GROUND_Y||x>W||x<0)break;
    const sz=Math.max(1.5,4-i*0.08);
    ctx.globalAlpha=Math.max(0.2,1-i*0.025);
    ctx.beginPath();ctx.arc(x,y,sz,0,Math.PI*2);ctx.fill();
  }
  ctx.globalAlpha=1;
}

function drawParticles(){
  for(const p of particles){
    const al=1-p.age/p.life;
    ctx.globalAlpha=al;
    ctx.fillStyle=p.color;
    ctx.beginPath();
    ctx.arc(p.x,p.y,p.r*(0.5+al*0.5),0,Math.PI*2);
    ctx.fill();
  }
  ctx.globalAlpha=1;
}

function drawHUD(){
  // panel backdrop
  ctx.fillStyle="rgba(0,0,0,0.35)";
  roundRect(0,0,W,52,0,0,12,12);
  ctx.fill();

  ctx.font="bold 22px sans-serif";
  ctx.textBaseline="middle";
  ctx.textAlign="left";
  ctx.fillStyle="#fff";
  ctx.fillText("SCORE "+score.toLocaleString(),20,26);

  ctx.textAlign="center";
  ctx.fillStyle="#ffe169";
  ctx.fillText("LEVEL "+(currentLevel+)+" · "+LEVELS[currentLevel].name.toUpperCase(),W/2,26);

  // birds remaining icons
  ctx.textAlign="right";
  ctx.fillStyle="#fff";
  ctx.font="bold 14px sans-serif";
  ctx.fillText("BIRDS",W-20-birdsRemaining*32-10,18);
  for(let i=0;i<birdsRemaining;i++){
    drawMiniBird(W-30-i*32,32,8);
  }
}
function drawMiniBird(cx,cy,r){
  ctx.save();
  ctx.translate(cx,cy);
  ctx.fillStyle="#c41e1e";
  ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();
  ctx.fillStyle="white";
  ctx.beginPath();ctx.arc(r*0.3,-r*0.2,r*0.25,0,Math.PI*2);ctx.fill();
  ctx.fillStyle="#111";
  ctx.beginPath();ctx.arc(r*0.35,-r*0.2,r*0.1,0,Math.PI*2);ctx.fill();
  ctx.fillStyle="#f5a623";
  ctx.beginPath();
  ctx.moveTo(r*0.7,0);ctx.lineTo(r*1.3,r*0.1);ctx.lineTo(r*0.7,r*0.3);
  ctx.closePath();ctx.fill();
  ctx.restore();
}
function roundRect(x,y,w,h,r1,r2,r3,r4){
  ctx.beginPath();
  ctx.moveTo(x+r1,y);
  ctx.lineTo(x+w-r2,y);ctx.arcTo(x+w,y,x+w,y+r2,r2);
  ctx.lineTo(x+w,y+h-r3);ctx.arcTo(x+w,y+h,x+w-r3,y+h,r3);
  ctx.lineTo(x+r4,y+h);ctx.arcTo(x,y+h,x,y+h-r4,r4);
  ctx.lineTo(x,y+r1);ctx.arcTo(x,y,x+r1,y,r1);
  ctx.closePath();
}

function drawOverlay(){
  if(state==="playing")return;
  ctx.fillStyle="rgba(0,0,0,0.55)";
  ctx.fillRect(0,0,W,H);
  ctx.textAlign="center";
  ctx.textBaseline="middle";

  if(state==="levelComplete"){
    ctx.fillStyle="#fff";
    ctx.font="bold 44px sans-serif";
    ctx.fillText("LEVEL CLEAR!",W/2,H/2-90);
    drawStarsRow(lastStars,W/2,H/2-20);
    ctx.font="20px sans-serif";
    ctx.fillStyle="#ffe169";
    ctx.fillText("Bonus: "+(birdsRemaining*10000).toLocaleString()+" pts",W/2,H/2+50);
    ctx.fillStyle="#ddd";
    ctx.font="18px sans-serif";
    ctx.fillText("CLICK TO CONTINUE",W/2,H/2+100);
  }else if(state==="allWon"){
    ctx.fillStyle="#ffe169";
    ctx.font="bold 50px sans-serif";
    ctx.fillText("YOU WIN!",W/2,H/2-110);
    ctx.fillStyle="#fff";
    ctx.font="22px sans-serif";
    ctx.fillText("FINAL SCORE: "+score.toLocaleString(),W/2,H/2-40);
    drawStarsRow(Math.round(totalStars/Math.max(1,currentLevel+1)),W/2,H/2+20);
    ctx.fillStyle="#ddd";
    ctx.font="18px sans-serif";
    ctx.fillText("CLICK TO PLAY AGAIN",W/2,H/2+90);
  }else if(state==="lost"){
    ctx.fillStyle="#ff7777";
    ctx.font="bold 50px sans-serif";
    ctx.fillText("OUT OF BIRDS",W/2,H/2-40);
    ctx.fillStyle="#fff";
    ctx.font="20px sans-serif";
    ctx.fillText("Press R to retry this level",W/2,H/2+30);
  }
}
function drawStarsRow(count,cx,cy){
  const gap=70;
  const startX=cx-gap*(count-1)/2;
  for(let i=0;i<3;i++){
    drawStar(startX+i*gap,cy,i<count?1:0.25,30);
  }
}
function drawStar(x,y,alpha,size){
  ctx.save();
  ctx.globalAlpha=alpha;
  ctx.translate(x,y);
  ctx.fillStyle=alpha>=1?"#ffd54a":"#666";
  ctx.beginPath();
  for(let i=0;i<5;i++){
    const a=-Math.PI/2+i*Math.PI*2/5;
    const r=size;
    ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);
    const ia=a+Math.PI/5;
    ctx.lineTo(Math.cos(ia)*r*0.45,Math.sin(ia)*r*0.45);
  }
  ctx.closePath();ctx.fill();
  ctx.strokeStyle="#b8860b";
  ctx.lineWidth=2;
  ctx.stroke();
  ctx.restore();
}

// ---------- Input ----------
function getMouse(e){
  const r=canvas.getBoundingClientRect();
  const sx=canvas.width/r.width, sy=canvas.height/r.height;
  return {x:(e.clientX-r.left)*sx, y:(e.clientY-r.top)*sy};
}

canvas.addEventListener("mousedown",e=>{
  e.preventDefault();
  if(state==="levelComplete"){startLevel(currentLevel+1);return;}
  if(state==="allWon"){currentLevel=0;score=0;totalStars=0;lastStars=0;startLevel(0);return;}
  if(state==="lost"){startLevel(currentLevel);return;}
  if(state!=="playing")return;
  if(!activeBird||!activeBird.onSling)return;
  const m=getMouse(e);
  if(Math.hypot(m.x-activeBird.x,m.y-activeBird.y)<50){
    dragging=true;
    dragPos={x:m.x,y:m.y};
    activeBird.x=m.x;activeBird.y=m.y;
  }
});
window.addEventListener("mousemove",e=>{
  if(!dragging)return;
  const m=getMouse(e);
  let mx=m.x,my=m.y;
  const dx=mx-SLING.x,dy=my-SLING.y;
  const mag=Math.hypot(dx,dy);
  if(mag>MAX_DRAG){
    mx=SLING.x+dx/mag*MAX_DRAG;
    my=SLING.y+dy/mag*MAX_DRAG;
  }
  if(mx>SLING.x-5)mx=SLING.x-5; // must pull left/down
  dragPos={x:mx,y:my};
  if(activeBird){activeBird.x=mx;activeBird.y=my;}
});
window.addEventListener("mouseup",e=>{
  if(!dragging)return;
  launchBird();
});

// Touch support
canvas.addEventListener("touchstart",e=>{
  e.preventDefault();
  const t=e.touches[0];
  canvas.dispatchEvent(new MouseEvent("mousedown",{clientX:t.clientX,clientY:t.clientY}));
},{passive:false});
canvas.addEventListener("touchmove",e=>{
  e.preventDefault();
  const t=e.touches[0];
  window.dispatchEvent(new MouseEvent("mousemove",{clientX:t.clientX,clientY:t.clientY}));
},{passive:false});
canvas.addEventListener("touchend",e=>{
  e.preventDefault();
  window.dispatchEvent(new MouseEvent("mouseup"));
},{passive:false});

document.addEventListener("keydown",e=>{
  if(e.key==="r"||e.key==="R"){startLevel(currentLevel);}
  if(e.key==="n"||e.key==="N"){
    if(currentLevel<LEVELS.length-1)startLevel(currentLevel+1);
    else state="allWon";
  }
});

// ---------- Boot ----------
startLevel(0);
let lastT=performance.now();
function loop(t){
  const dt=Math.min((t-lastT)/1000,1/30);
  lastT=t;
  update(dt);
  render();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

})();
</script>
