function getTouchPos(t){
  const r=canvas.getBoundingClientRect();
  const sx=canvas.width/r.width, sy=canvas.height/r.height;
  return {x:(t.clientX-r.left)*sx, y:(t.clientY-r.top)*sy};
}

canvas.addEventListener("touchstart",e=>{
  e.preventDefault();
  if(state==="levelComplete"){startLevel(currentLevel+1);return;}
  if(state==="allWon"){resetAll();return;}
  if(state==="lost"){startLevel(currentLevel);return;}
  if(state!=="playing"||!activeBird||!activeBird.onSling)return;
  const m=getTouchPos(e.touches[0]);
  if(Math.hypot(m.x-activeBird.x,m.y-activeBird.y)<60){
    dragging=true;
    dragPos={x:m.x,y:m.y};
    activeBird.x=m.x;activeBird.y=m.y;
  }
},{passive:false});
canvas.addEventListener("touchmove",e=>{
  e.preventDefault();
